-- Later phases extend the initial schema; applied migrations remain immutable.
ALTER TABLE channels ALTER COLUMN guild_id DROP NOT NULL;
ALTER TABLE channels DROP CONSTRAINT channels_type_check;
ALTER TABLE channels ADD CONSTRAINT channels_type_check CHECK(type IN ('category','text','voice','video','announcement','forum','thread','dm','group_dm'));
ALTER TABLE channels ADD COLUMN dm_user_low_id uuid REFERENCES users(id),ADD COLUMN dm_user_high_id uuid REFERENCES users(id),ADD COLUMN group_owner_id uuid REFERENCES users(id),ADD COLUMN icon_asset_id uuid REFERENCES media_assets(id);
ALTER TABLE channels ADD CONSTRAINT channel_scope CHECK((guild_id IS NOT NULL AND type NOT IN ('dm','group_dm') AND dm_user_low_id IS NULL AND dm_user_high_id IS NULL AND group_owner_id IS NULL) OR (guild_id IS NULL AND parent_id IS NULL AND ((type='dm' AND dm_user_low_id<dm_user_high_id AND group_owner_id IS NULL) OR (type='group_dm' AND dm_user_low_id IS NULL AND dm_user_high_id IS NULL AND group_owner_id IS NOT NULL))));
CREATE UNIQUE INDEX dm_pair ON channels(dm_user_low_id,dm_user_high_id) WHERE type='dm';
CREATE OR REPLACE FUNCTION check_channel_parent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM channels WHERE id=NEW.parent_id AND guild_id=NEW.guild_id AND deleted_at IS NULL AND ((NEW.type='thread' AND type='forum') OR (NEW.type NOT IN ('thread','category') AND type='category'))) THEN RAISE EXCEPTION 'Invalid parent' USING ERRCODE='23514'; END IF;
 IF NEW.type='thread' AND NEW.parent_id IS NULL THEN RAISE EXCEPTION 'Thread needs forum' USING ERRCODE='23514';END IF;
 RETURN NEW;END $$;
CREATE TABLE channel_members(channel_id uuid NOT NULL REFERENCES channels(id),user_id uuid NOT NULL REFERENCES users(id),joined_at timestamptz NOT NULL DEFAULT now(),left_at timestamptz,muted_until timestamptz,PRIMARY KEY(channel_id,user_id));
CREATE INDEX channel_members_user ON channel_members(user_id);
CREATE TABLE guild_bans(guild_id uuid NOT NULL REFERENCES guilds(id),user_id uuid NOT NULL REFERENCES users(id),banned_by uuid REFERENCES users(id),reason varchar(1000),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,PRIMARY KEY(guild_id,user_id));
CREATE TABLE themes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),guild_id uuid REFERENCES guilds(id),name varchar(64) NOT NULL,visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','guild')),base_mode text NOT NULL CHECK(base_mode IN ('dark','light')),palette jsonb NOT NULL,schema_version smallint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,CHECK((visibility='private' AND guild_id IS NULL) OR (visibility='guild' AND guild_id IS NOT NULL)));
CREATE INDEX themes_guild ON themes(guild_id,visibility);
ALTER TABLE guilds ADD COLUMN theme_id uuid REFERENCES themes(id);
ALTER TABLE user_preferences DROP CONSTRAINT user_preferences_theme_mode_check;
ALTER TABLE user_preferences ADD CONSTRAINT user_preferences_theme_mode_check CHECK(theme_mode IN ('dark','light','custom'));
ALTER TABLE user_preferences ADD COLUMN theme_id uuid REFERENCES themes(id);
CREATE TABLE custom_emojis(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),guild_id uuid NOT NULL REFERENCES guilds(id),name varchar(32) NOT NULL CHECK(name ~ '^[A-Za-z0-9_]{2,32}$'),asset_id uuid NOT NULL REFERENCES media_assets(id),created_by uuid NOT NULL REFERENCES users(id),animated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE UNIQUE INDEX emoji_name ON custom_emojis(guild_id,lower(name)) WHERE deleted_at IS NULL;
CREATE TABLE custom_stickers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),guild_id uuid NOT NULL REFERENCES guilds(id),name varchar(64) NOT NULL,asset_id uuid NOT NULL REFERENCES media_assets(id),created_by uuid NOT NULL REFERENCES users(id),tags text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE UNIQUE INDEX sticker_name ON custom_stickers(guild_id,lower(name)) WHERE deleted_at IS NULL;
CREATE INDEX sticker_tags ON custom_stickers USING gin(tags);
CREATE TABLE custom_sound_effects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),guild_id uuid NOT NULL REFERENCES guilds(id),name varchar(64) NOT NULL,asset_id uuid NOT NULL REFERENCES media_assets(id),created_by uuid NOT NULL REFERENCES users(id),category varchar(64) NOT NULL DEFAULT 'Geral',default_shortcut varchar(64),duration_ms integer NOT NULL CHECK(duration_ms BETWEEN 1 AND 10000),volume real NOT NULL DEFAULT 1 CHECK(volume BETWEEN 0 AND 2),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE UNIQUE INDEX sound_name ON custom_sound_effects(guild_id,lower(name)) WHERE deleted_at IS NULL;
CREATE TABLE message_custom_emojis(message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,emoji_id uuid NOT NULL REFERENCES custom_emojis(id),PRIMARY KEY(message_id,emoji_id));
CREATE TABLE message_stickers(message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,sticker_id uuid NOT NULL REFERENCES custom_stickers(id),position smallint NOT NULL DEFAULT 0 CHECK(position>=0),PRIMARY KEY(message_id,sticker_id),UNIQUE(message_id,position));
CREATE TABLE message_reactions(message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),emoji_key text NOT NULL,unicode_emoji text,custom_emoji_id uuid REFERENCES custom_emojis(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(message_id,user_id,emoji_key),CHECK((unicode_emoji IS NOT NULL)::int+(custom_emoji_id IS NOT NULL)::int=1),CHECK((unicode_emoji IS NOT NULL AND emoji_key='u:'||unicode_emoji) OR (custom_emoji_id IS NOT NULL AND emoji_key='c:'||custom_emoji_id::text)));
CREATE INDEX reactions_message ON message_reactions(message_id,emoji_key);
CREATE OR REPLACE FUNCTION valid_message_body() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE mid uuid; BEGIN
 IF TG_TABLE_NAME='messages' THEN mid:=NEW.id; ELSE mid:=OLD.message_id;END IF;
 IF EXISTS(SELECT 1 FROM messages WHERE id=mid AND deleted_at IS NULL AND length(trim(content))=0) AND NOT EXISTS(SELECT 1 FROM message_attachments WHERE message_id=mid) AND NOT EXISTS(SELECT 1 FROM message_stickers WHERE message_id=mid) THEN RAISE EXCEPTION 'Empty message' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER sticker_preserves_body AFTER DELETE OR UPDATE ON message_stickers DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION valid_message_body();
CREATE TABLE user_soundboard_shortcuts(user_id uuid NOT NULL REFERENCES users(id),sound_effect_id uuid NOT NULL REFERENCES custom_sound_effects(id),shortcut varchar(64) NOT NULL,PRIMARY KEY(user_id,sound_effect_id),UNIQUE(user_id,shortcut));
CREATE TABLE voice_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),channel_id uuid NOT NULL REFERENCES channels(id),provider_room_name text NOT NULL UNIQUE,started_by uuid NOT NULL REFERENCES users(id),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
CREATE UNIQUE INDEX voice_active_channel ON voice_sessions(channel_id) WHERE ended_at IS NULL;
CREATE TABLE voice_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voice_session_id uuid NOT NULL REFERENCES voice_sessions(id),user_id uuid NOT NULL REFERENCES users(id),provider_participant_identity text NOT NULL UNIQUE,joined_at timestamptz NOT NULL DEFAULT now(),left_at timestamptz,self_muted boolean NOT NULL DEFAULT false,self_deafened boolean NOT NULL DEFAULT false,server_muted boolean NOT NULL DEFAULT false,server_deafened boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX voice_active_user ON voice_participants(user_id) WHERE left_at IS NULL;
CREATE TABLE voice_tracks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),participant_id uuid NOT NULL REFERENCES voice_participants(id),provider_track_sid text NOT NULL UNIQUE,source text NOT NULL CHECK(source IN ('microphone','camera','screen_video','screen_audio','soundboard')),width integer,height integer,fps smallint CHECK(fps BETWEEN 1 AND 60),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
CREATE UNIQUE INDEX voice_track_active ON voice_tracks(participant_id,source) WHERE ended_at IS NULL;
CREATE TABLE user_voice_preferences(user_id uuid NOT NULL REFERENCES users(id),target_user_id uuid NOT NULL REFERENCES users(id),volume real NOT NULL DEFAULT 1 CHECK(volume BETWEEN 0 AND 2),muted_locally boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,target_user_id),CHECK(user_id<>target_user_id));
CREATE TABLE soundboard_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voice_session_id uuid NOT NULL REFERENCES voice_sessions(id),sound_effect_id uuid NOT NULL REFERENCES custom_sound_effects(id),triggered_by uuid NOT NULL REFERENCES users(id),client_nonce uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(triggered_by,client_nonce));
CREATE TABLE friend_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL REFERENCES users(id),recipient_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),responded_at timestamptz,CHECK(sender_id<>recipient_id));
CREATE UNIQUE INDEX friend_pending ON friend_requests(least(sender_id,recipient_id),greatest(sender_id,recipient_id)) WHERE status='pending';
CREATE TABLE friendships(user_low_id uuid NOT NULL REFERENCES users(id),user_high_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_low_id,user_high_id),CHECK(user_low_id<user_high_id));
CREATE INDEX friendships_high ON friendships(user_high_id);
CREATE TABLE user_blocks(blocker_id uuid NOT NULL REFERENCES users(id),blocked_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
ALTER TABLE notifications DROP CONSTRAINT notifications_kind_check;
ALTER TABLE notifications ADD CONSTRAINT notifications_kind_check CHECK(kind IN ('mention','role_mention','everyone_mention','direct_message','friend_request','system'));
ALTER TABLE notifications ADD COLUMN friend_request_id uuid REFERENCES friend_requests(id);
CREATE TABLE notification_preferences(user_id uuid PRIMARY KEY REFERENCES users(id),desktop_enabled boolean NOT NULL DEFAULT false,sound_enabled boolean NOT NULL DEFAULT true,direct_messages boolean NOT NULL DEFAULT true,mentions boolean NOT NULL DEFAULT true,everyone_mentions boolean NOT NULL DEFAULT true,quiet_hours_enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),weekday smallint NOT NULL CHECK(weekday BETWEEN 1 AND 7),start_local time NOT NULL,end_local time NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(start_local<end_local),UNIQUE(user_id,weekday,start_local,end_local));
CREATE TABLE user_notification_sounds(user_id uuid NOT NULL REFERENCES users(id),event text NOT NULL CHECK(event IN ('message','call_join','call_leave')),asset_id uuid REFERENCES media_assets(id),enabled boolean NOT NULL DEFAULT true,volume real NOT NULL DEFAULT 1 CHECK(volume BETWEEN 0 AND 1),PRIMARY KEY(user_id,event));
CREATE TABLE push_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),auth_session_id uuid NOT NULL REFERENCES auth_sessions(id),endpoint text NOT NULL UNIQUE,p256dh text NOT NULL,auth_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_success_at timestamptz,revoked_at timestamptz);
CREATE TABLE notification_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notification_id uuid NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,subscription_id uuid NOT NULL REFERENCES push_subscriptions(id),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sent','failed','suppressed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz,sent_at timestamptz,last_error_code varchar(64),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(notification_id,subscription_id));
CREATE INDEX push_pending ON notification_deliveries(state,next_attempt_at);
CREATE INDEX messages_search ON messages USING gin(to_tsvector('simple',content)) WHERE deleted_at IS NULL;
